package net.officefloor.hq.app.person;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface PersonRepository extends JpaRepository<Person, Long> {

    /** The sheet's people in list order: by their place, a person added later at the end. */
    @Query("select p from Person p where p.sheetId = :sheetId order by coalesce(p.position, p.id), p.id")
    List<Person> findListed(@Param("sheetId") String sheetId);

    /** Sets a person's place in the list, leaving their version as it is: a move is no edit of them. */
    @Modifying(flushAutomatically = true, clearAutomatically = true)
    @Query("update Person p set p.position = :position where p.id = :id")
    void placeAt(@Param("id") Long id, @Param("position") long position);

    Optional<Person> findByIdAndSheetId(Long id, String sheetId);

    /** The people on the sheet with the name, ignoring case. */
    List<Person> findBySheetIdAndNameIgnoreCase(String sheetId, String name);

    /** Whether the name is in use on the sheet, ignoring case. */
    boolean existsBySheetIdAndNameIgnoreCase(String sheetId, String name);

    /** Whether the name is in use on the sheet by someone other than this person, ignoring case. */
    boolean existsBySheetIdAndNameIgnoreCaseAndIdNot(String sheetId, String name, Long id);

    /** Whether the contact is someone's on the sheet. */
    boolean existsBySheetIdAndContact(String sheetId, String contact);

    /** Whether the contact is on the sheet for someone other than this person. */
    boolean existsBySheetIdAndContactAndIdNot(String sheetId, String contact, Long id);

    /** The people on any of the sheets. */
    List<Person> findBySheetIdIn(java.util.Collection<String> sheetIds);
}
package net.officefloor.hq.app.person;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;

public interface PersonAliasRepository extends JpaRepository<PersonAlias, Long> {

    /** The sheet's aliases in the order they were added. */
    List<PersonAlias> findBySheetIdOrderByIdAsc(String sheetId);

    /** The person's aliases in the order they were added. */
    List<PersonAlias> findByPersonIdOrderByIdAsc(Long personId);

    /** Whether the alias is in use on the sheet, ignoring case. */
    boolean existsBySheetIdAndAliasIgnoreCase(String sheetId, String alias);

    /** The aliases on any of the sheets. */
    List<PersonAlias> findBySheetIdIn(java.util.Collection<String> sheetIds);

    Optional<PersonAlias> findFirstBySheetIdAndAliasIgnoreCase(String sheetId, String alias);

    /** The person on the sheet going by the name or alias, ignoring case. */
    static Optional<Person> findByNameOrAlias(List<Person> onSheet, PersonAliasRepository aliases, String sheetId,
            String name) {
        Optional<Person> named = onSheet.stream().filter(p -> p.getName().equalsIgnoreCase(name)).findFirst();
        if (named.isPresent()) {
            return named;
        }
        return aliases.findFirstBySheetIdAndAliasIgnoreCase(sheetId, name)
                .flatMap(a -> onSheet.stream().filter(p -> p.getId().equals(a.getPersonId())).findFirst());
    }
}
